# Run DP benchmark on a simulated dataset
# Input: data_simulation/data/simulated_for_benchmark.csv (generated by simulate_for_dp_benchmark.R)
# Output: dp_global/dev/transition_time_measurements.csv
rm(list = ls())

library(data.table)
library(here)

# Config
INPUT_FILE <- here::here("data_simulation", "data", "simulated_for_benchmark.csv")
OUT_MEAS <- here::here("dp_global", "dev", "transition_time_measurements.csv")
ANCHOR_START <- 7L
N_REP <- 3L
TIMEOUT_SEC <- 300
PRUNE_HARD <- FALSE
PRUNE_MIN_GROWTH <- -0.5
PRUNE_MAX_GROWTH <- 7.5
PRUNE_RECRUIT_MAX_DBH <- 7.5 * 5
SHOW_PROGRESS <- TRUE

# Load dp core quietly
dp_main <- here::here("dp_global", "R", "dp_global_main.R")
if (!file.exists(dp_main)) stop("dp_global_main.R not found: ", dp_main)
suppressWarnings(suppressMessages(sys.source(dp_main, envir = globalenv())))

# Read data
if (!file.exists(INPUT_FILE)) stop("Simulated dataset not found: ", INPUT_FILE)
xs_all <- fread(INPUT_FILE)

# compute_transition_table(...) - Compute per-Tag TransitionComputations used as a proxy
# for DP computational load. For each Tag we count observations per census up to the
# anchor, compute the number of injective assignment states (P(K, n) = K!/(K-n)!) for
# each census where n is the number of observations and K is approximated by the max
# observed across censuses (plus slack, if applicable). TransitionComputations is the
# sum over adjacent census transitions of (n_states_t * n_states_t+1), an estimate of the
# number of state-pair transition cost evaluations the DP would need in the worst case.
# Returns a data.table(Tag, TransitionComputations).
compute_transition_table <- function(xs, anchor_start = ANCHOR_START) {
  xs <- copy(xs)
  setDT(xs)
  key <- paste(xs$Tag, xs$CensusID, sep = ":::")
  key_non_na <- key[!is.na(xs$DBH)]
  cnts <- collapse::fcount(key_non_na)
  if (is.data.frame(cnts)) {
    keys <- as.character(cnts$x); vals <- as.integer(cnts$N)
  } else {
    keys <- names(cnts); vals <- if (is.list(cnts)) as.integer(unlist(cnts)) else as.integer(cnts)
  }
  spl <- strsplit(keys, ":::")
  split_k <- do.call(rbind, spl)
  dt_counts <- data.table(Tag = split_k[,1], CensusID = as.integer(split_k[,2]), n = vals)
  dt_counts_anchor <- dt_counts[CensusID <= anchor_start]
  wide <- data.table::dcast(dt_counts_anchor, Tag ~ CensusID, value.var = "n", fill = 0)
  census_cols <- as.character(seq_len(anchor_start))
  missing_cols <- setdiff(census_cols, setdiff(names(wide), "Tag"))
  for (col in missing_cols) wide[, (col) := 0L]
  setcolorder(wide, c("Tag", census_cols))
  mat <- as.matrix(wide[, ..census_cols])
  K_mat <- matrix(as.integer(do.call(pmax, as.data.frame(mat))), nrow = nrow(mat), ncol = ncol(mat))
  n_obs_mat <- mat
  n_states_mat <- matrix(NA_real_, nrow = nrow(mat), ncol = ncol(mat))
  n_states_mat[n_obs_mat == 0] <- 1
  ok_mask <- (n_obs_mat != 0) & (n_obs_mat <= K_mat)
  if (any(ok_mask)) {
    n_states_mat[ok_mask] <- exp(lgamma(K_mat[ok_mask] + 1) - lgamma(K_mat[ok_mask] - n_obs_mat[ok_mask] + 1))
  }
  transition_computations <- rowSums(n_states_mat[, -ncol(n_states_mat), drop = FALSE] * n_states_mat[, -1, drop = FALSE])
  data.table(Tag = wide$Tag, TransitionComputations = transition_computations)
}

res_tab <- compute_transition_table(xs_all, anchor_start = ANCHOR_START)
# filter tags up to TC <= 2,000,000
res_tab <- res_tab[TransitionComputations <= 3e6]
setorder(res_tab, TransitionComputations)

# time_tag_run(tag_val) - Run DP for a single tag and measure elapsed time.
# - Performs one warmup run (to exercise compilation/initialization) and then n_rep timed runs.
# - Uses R.utils::withTimeout() to abort runs that exceed TIMEOUT_SEC and records NA for failures.
# - Passes pruning parameters (PRUNE_*) into the DP function so timings reflect the
#   pruning configuration you selected above.
# - Returns: list(tag, times (vector), median (median of valid times or NA), n_valid, errors)
#
# Note: warmup errors are recorded but do not stop timing; individual runs that error
#       produce NA and are excluded from the median calculation.
#
# Usage example:
#   r <- time_tag_run('nstem_3', n_rep = 3, timeout = 300)
#   r$median  # median runtime in seconds (or NA)

time_tag_run <- function(tag_val, n_rep = N_REP, timeout = TIMEOUT_SEC) {
  td <- xs_all[Tag == tag_val]
  td <- as.data.table(td)
  errors <- character(0)
  # Warmup: run once (silently) to trigger any compilation or setup overhead
  tryCatch(R.utils::withTimeout(match_stems_dp_global_backward_marginals_batch(td, anchor_start = ANCHOR_START, prune_hard = PRUNE_HARD, prune_min_growth = PRUNE_MIN_GROWTH, prune_max_growth = PRUNE_MAX_GROWTH, prune_recruit_max_dbh = PRUNE_RECRUIT_MAX_DBH, verbose = FALSE), timeout = timeout, onTimeout = "error"), error = function(e) { errors <<- c(errors, e$message); return(NA) })

  times <- numeric(0)
  for (i in seq_len(n_rep)) {
    t <- tryCatch(R.utils::withTimeout({ st <- proc.time()[[3]]; out <- match_stems_dp_global_backward_marginals_batch(td, anchor_start = ANCHOR_START, prune_hard = PRUNE_HARD, prune_min_growth = PRUNE_MIN_GROWTH, prune_max_growth = PRUNE_MAX_GROWTH, prune_recruit_max_dbh = PRUNE_RECRUIT_MAX_DBH, verbose = FALSE); en <- proc.time()[[3]]; en - st }, timeout = timeout, onTimeout = "error"), error = function(e) { errors <<- c(errors, e$message); NA_real_ })
    times <- c(times, t)
    if (SHOW_PROGRESS) message(sprintf("Tag=%s run %d/%d time=%s", tag_val, i, n_rep, ifelse(is.na(t), "NA", sprintf("%.3fs", t))))
  }
  list(tag = tag_val, times = times, median = if (all(is.na(times))) NA_real_ else median(times, na.rm = TRUE), n_valid = sum(!is.na(times)), errors = unique(errors))
}

# Run timing for each tag
results <- list()
for (tg in res_tab$Tag) {
  if (SHOW_PROGRESS) message(sprintf("Starting Tag=%s (TC=%s)", tg, res_tab[Tag == tg, TransitionComputations]))
  r <- time_tag_run(tg)
  results[[tg]] <- r
}

beepr::beep(2)

res_meas <- rbindlist(lapply(results, function(x) data.table(Tag = x$tag, MedianSec = x$median, NValid = x$n_valid)))
res_meas <- merge(res_meas, res_tab, by = "Tag", all.x = TRUE)
setorder(res_meas, TransitionComputations)

fwrite(res_meas, file = OUT_MEAS)

m0 <- lm(log10(MedianSec) ~ log10(TransitionComputations), data = res_meas)

m_poly <- lm(
    log10(MedianSec) ~ poly(log10(TransitionComputations), 2, raw = TRUE),
    data = res_meas
)

anova(m0, m_poly)
AIC(m0)
AIC(m_poly)
# prediction grid
pred_vals <- data.table(
    TransitionComputations = exp(
        seq(
            log(min(res_meas$TransitionComputations)),
            log(max(res_meas$TransitionComputations)),
            length.out = 200
        )
    )
)

pred_vals[, PredictedSec :=
    10^(
        predict(
            m_poly,
            newdata = pred_vals
        )
    )]

with(
    res_meas,
    plot(
        MedianSec ~ TransitionComputations,
        log = "xy",
        pch = 16,
        xlab = "Transition Computations",
        ylab = "Median Time (s)",
        main = "Polynomial fit in log-log space"
    )
)

lines(
    PredictedSec ~ TransitionComputations,
    data = pred_vals,
    col = "blue",
    lwd = 2
)

# predict_time(N, unit = c("sec","min","hour")) - Predict runtime from TransitionComputations.
# - N: numeric scalar or vector of TransitionComputations
# - unit: one of "sec" (seconds), "min" (minutes), or "hour" (hours). Default is "sec".
predict_time <- function(N, unit = c("sec", "min", "hour")) {
    unit <- match.arg(unit)
    logN <- log10(N)
    logT <- -1.45817 +
        (-0.07313 * logN) +
        (0.14164 * logN^2)
    secs <- 10^logT
    out <- switch(unit,
        sec = secs,
        min = secs / 60,
        hour = secs / 3600
    )
    out
}

# Examples: predictions in seconds, minutes, and hours
predict_time(1000, "sec")
predict_time(1000, "min")
predict_time(1e6, "hour")
round(predict_time(c(10, 100, 1000, 1e5, 1e6, 1e7), "min"), 4)

round(predict_time(c(10, 100, 1000, 1e5, 1e6, 1e7), "hour"), 4)
